import java.util.*;

public class MyCalendarThree {
    List<int[]> bookings = new ArrayList<>();

    int book(int start, int end) {
        bookings.add(new int[]{start, end});
        List<int[]> events = new ArrayList<>();
        for (int[] b : bookings) {                     // re-collect marks from EVERY booking
            events.add(new int[]{b[0], 1});
            events.add(new int[]{b[1], -1});
        }
        events.sort((a, c) -> a[0] != c[0] ? a[0] - c[0] : a[1] - c[1]);  // re-sort every call

        int cur = 0, best = 0;
        for (int[] e : events) {
            cur += e[1];
            best = Math.max(best, cur);
        }
        return best;
    }
}

