#include <bits/stdc++.h>
using namespace std;

class MyCalendarThree {
public:
    vector<pair<int,int>> bookings;

    int book(int start, int end) {
        bookings.push_back({start, end});
        vector<pair<int,int>> events;
        for (auto& b : bookings) {                       // re-collect marks from EVERY booking
            events.push_back({b.first, 1});
            events.push_back({b.second, -1});
        }
        sort(events.begin(), events.end());                // re-sort every call

        int cur = 0, best = 0;
        for (auto& e : events) {
            cur += e.second;
            best = max(best, cur);
        }
        return best;
    }
};

