import java.util.*;

public class MyCalendarThree {
    TreeMap<Integer, Integer> deltas = new TreeMap<>();  // persists across calls

    int book(int start, int end) {
        deltas.merge(start, 1, Integer::sum);
        deltas.merge(end, -1, Integer::sum);

        int cur = 0, best = 0;
        for (int delta : deltas.values()) {    // sweep the whole (already sorted) structure once
            cur += delta;
            best = Math.max(best, cur);
        }
        return best;
    }
}

