#include <bits/stdc++.h>
using namespace std;

class MyCalendarThree {
public:
    map<int,int> deltas;   // persists across calls, kept sorted automatically

    int book(int start, int end) {
        deltas[start]++;
        deltas[end]--;

        int cur = 0, best = 0;
        for (auto& [time, delta] : deltas) {    // sweep the whole (already sorted) structure once
            cur += delta;
            best = max(best, cur);
        }
        return best;
    }
};
